// Generated by npm run prepare:supabase. Edit the original Joy payroll source instead.
export const DEFAULT_ACCOMMODATION_TYPES = [
  "Tamil / Own Accommodation",
  "Outside Room",
  "Joy Room",
] as const;

export function isOwnOrTamilAccommodation(val: unknown): boolean {
  if (!val || typeof val !== "string") return true;
  const s = val.trim().toLowerCase();
  return (
    s === "" ||
    s === "none" ||
    s === "own" ||
    s === "tamil" ||
    s === "tamil own" ||
    s === "own accommodation" ||
    s === "tamil accommodation" ||
    s === "tamil / own accommodation" ||
    s === "tamil / own" ||
    s.includes("own") ||
    s.includes("tamil")
  );
}

export function normalizeAccommodationType(value: unknown) {
  const normalized = typeof value === "string" ? value.trim() : "";
  if (!normalized) return "Tamil / Own Accommodation";
  const lower = normalized.toLowerCase();
  if (
    lower === "tamil" ||
    lower === "tamil own" ||
    lower === "own" ||
    lower === "own accommodation" ||
    lower === "tamil / own accommodation" ||
    lower === "tamil accommodation" ||
    lower === "none"
  ) {
    return "Tamil / Own Accommodation";
  }
  if (lower === "joy" || lower === "joy hostel" || lower === "joy room") {
    return "Joy Room";
  }
  if (lower === "outside" || lower === "outside room" || lower === "outside hostel") {
    return "Outside Room";
  }
  return normalized;
}

export function normalizedScope(value: unknown): string[] {
  const parsed = typeof value === "string" ? parseScopeJson(value) : value;
  if (!Array.isArray(parsed)) return [];
  return [...new Set(parsed.filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0).map((entry) => entry.trim()))].sort();
}

function parseScopeJson(value: string): unknown {
  try { return JSON.parse(value); } catch { return []; }
}

export function calendarPeriod(period: string) {
  const [year, month] = period.split("-").map(Number);
  const start = `${period}-01`;
  const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return { start, end: `${period}-${String(lastDay).padStart(2, "0")}`, days: lastDay };
}

export function payrollPeriodRange(period: string, periodStart?: string | null, periodEnd?: string | null) {
  const defaults = calendarPeriod(period);
  const start = periodStart || defaults.start;
  const inclusiveEnd = periodEnd || defaults.end;
  const startDate = new Date(`${start}T00:00:00.000Z`);
  const endDate = new Date(`${inclusiveEnd}T00:00:00.000Z`);
  const duration = Math.round((endDate.getTime() - startDate.getTime()) / 86400000) + 1;
  endDate.setUTCDate(endDate.getUTCDate() + 1);
  return { start, end: endDate.toISOString().slice(0, 10), inclusiveEnd, days: duration };
}

export function recoveryAllowedDateRange(payPeriod: string, periodStart?: string | null, periodEnd?: string | null) {
  const [year, month] = payPeriod.split("-").map(Number);
  const prevDate = new Date(Date.UTC(year, month - 2, 1));
  const prevYear = prevDate.getUTCFullYear();
  const prevMonth = prevDate.getUTCMonth() + 1;
  const prevMonthStart = `${prevYear}-${String(prevMonth).padStart(2, "0")}-01`;

  const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
  const payPeriodEnd = `${payPeriod}-${String(lastDay).padStart(2, "0")}`;

  const cycleStart = periodStart || `${payPeriod}-01`;
  const cycleEnd = periodEnd || payPeriodEnd;

  const allowedStart = cycleStart < prevMonthStart ? cycleStart : prevMonthStart;
  const allowedEnd = cycleEnd > payPeriodEnd ? cycleEnd : payPeriodEnd;

  return { allowedStart, allowedEnd };
}

export function splitMoneyEqually(amount: number, count: number): number[] {
  if (!Number.isSafeInteger(count) || count < 1) return [];
  const pennies = Math.round(Math.max(0, amount) * 100);
  const base = Math.floor(pennies / count);
  const remainder = pennies % count;
  return Array.from({ length: count }, (_, index) => (base + (index < remainder ? 1 : 0)) / 100);
}

export function splitRoomExpenses(
  amounts: {
    gasAmount: number;
    rationAmount: number;
    provisionAmount: number;
    roomRentAmount?: number;
    transportRentAmount?: number;
  },
  employeeIds: string[],
) {
  const uniqueEmployees = [...new Set(employeeIds)].sort();
  const gas = splitMoneyEqually(amounts.gasAmount, uniqueEmployees.length);
  const ration = splitMoneyEqually(amounts.rationAmount, uniqueEmployees.length);
  const provision = splitMoneyEqually(amounts.provisionAmount, uniqueEmployees.length);
  const rent = splitMoneyEqually(amounts.roomRentAmount ?? 0, uniqueEmployees.length);
  const transport = splitMoneyEqually(amounts.transportRentAmount ?? 0, uniqueEmployees.length);
  return uniqueEmployees.map((employeeId, index) => ({
    employeeId,
    gasShare: gas[index],
    rationShare: ration[index],
    provisionShare: provision[index],
    rentShare: rent[index],
    transportShare: transport[index],
    total:
      Math.round(
        (gas[index] +
          ration[index] +
          provision[index] +
          rent[index] +
          transport[index]) *
          100,
      ) / 100,
  }));
}

